PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS state (id INTEGER PRIMARY KEY CHECK(id=1), version INTEGER NOT NULL, token TEXT NOT NULL, body TEXT NOT NULL);
INSERT OR IGNORE INTO state VALUES(1,0,'','{"symbols":{},"comments":{},"jobs":{},"cursor":null,"desktop":{}}');
CREATE TABLE IF NOT EXISTS events (sequence INTEGER PRIMARY KEY AUTOINCREMENT, id TEXT UNIQUE NOT NULL, at TEXT NOT NULL, actor TEXT NOT NULL, action TEXT NOT NULL, body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS requests (id TEXT PRIMARY KEY, hash TEXT NOT NULL, response TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS revisions (id TEXT PRIMARY KEY, symbol TEXT NOT NULL, parent TEXT, fingerprint TEXT NOT NULL, at TEXT NOT NULL, body TEXT NOT NULL, public TEXT NOT NULL, migration INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS publication (id INTEGER PRIMARY KEY CHECK(id=1), body TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS revisions_symbol ON revisions(symbol);
CREATE TABLE IF NOT EXISTS assets (hash TEXT PRIMARY KEY, mime TEXT NOT NULL, body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (hash TEXT PRIMARY KEY, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS attempts (key TEXT PRIMARY KEY, count INTEGER NOT NULL, until INTEGER NOT NULL);
